                    UPDATE message_draft_revision_clock SET revision = revision + 1;
                    UPDATE message_draft_revisions SET revision =
                        (SELECT revision FROM message_draft_revision_clock)
                        WHERE group_id_hex = NEW.group_id_hex;
                END;
